import { getDataValue } from "@lumeland/core/utils/data-values.ts";
import { merge } from "@lumeland/core/utils/object.ts";
import { Page } from "@lumeland/core/file.ts";
import { XMLBuilder } from "../deps/xml.js";
// Default options
export const defaults = {
    filename: "/sitemap.xml",
    query: "unlisted!=true",
    sort: "url=asc",
    items: {
        lastmod: "=date",
    },
};
/**
 * A plugin to generate a sitemap.xml from page files after build
 * @see https://lume.land/plugins/sitemap/
 */
export function sitemap(userOptions) {
    const options = merge(defaults, userOptions);
    return (site) => {
        site.process(async function processSitemap() {
            // Create the sitemap.xml page
            const sitemap = Page.create({
                url: options.filename,
                content: generateSitemap(site.search.pages(options.query, options.sort)),
            });
            // Add the sitemap page to pages
            site.pages.push(sitemap);
            // Add or update `robots.txt` with the sitemap url
            const robots = await site.getOrCreatePage("/robots.txt");
            robots.text = `${robots.text}\nSitemap: ${site.url(options.filename, true)}\n`;
        });
        function generateSitemap(pages) {
            const builder = new XMLBuilder({
                ignoreAttributes: false,
                suppressEmptyNode: true,
                attributeNamePrefix: "@",
                cdataPropName: "_html",
                format: true,
            });
            const items = options.items ?? {};
            const sitemap = {
                "?xml": {
                    "@version": "1.0",
                    "@encoding": "UTF-8",
                },
                "?xml-stylesheet": options.stylesheet
                    ? {
                        "@type": "text/xsl",
                        "@href": options.stylesheet,
                    }
                    : undefined,
                urlset: {
                    "@xmlns": "http://www.sitemaps.org/schemas/sitemap/0.9",
                    "@xmlns:xhtml": "http://www.w3.org/1999/xhtml",
                    url: pages.map((data) => {
                        const node = {
                            loc: site.url(data.url, true),
                        };
                        const lastmod = getDataValue(data, items.lastmod);
                        if (lastmod instanceof Date) {
                            node.lastmod = lastmod.toISOString();
                        }
                        const changefreq = getDataValue(data, items.changefreq);
                        if (changefreq) {
                            node.changefreq = changefreq;
                        }
                        const priority = getDataValue(data, items.priority);
                        if (typeof priority === "number") {
                            node.priority = priority;
                        }
                        if (data.alternates?.length) {
                            node["xhtml:link"] = data.alternates.map((alternate) => ({
                                "@rel": "alternate",
                                "@hreflang": alternate.lang,
                                "@href": site.url(alternate.url, true),
                            }));
                        }
                        if (data.unmatchedLangUrl) {
                            node["xhtml:link"]?.push({
                                "@rel": "alternate",
                                "@hreflang": "x-default",
                                "@href": site.url(data.unmatchedLangUrl, true),
                            });
                        }
                        return node;
                    }),
                },
            };
            return builder.build(sitemap);
        }
    };
}
export default sitemap;
